<script setup lang="ts">
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { api, ApiError, type EmployeeAccess, type EmployeeScopeCommand } from '../api'
import { useSession } from '../session'
import { captureRequestScope } from '../request-scope'
const props=defineProps<{access:EmployeeAccess}>(),emit=defineEmits<{changed:[]}>(),auth=useSession()
const choices=[['asset.read','查看客户与设备'],['asset.manage','维护客户与设备'],['identity.customer.provision','开通客户账号'],['ticket.read','查看授权工单'],['ticket.accept','受理工单'],['ticket.reject','驳回工单'],['ticket.assign','分派工单'],['ticket.engineer.read','查看工程师工单'],['ticket.assignment.accept','工程师接单'],['ticket.record','记录处理'],['ticket.solution.submit','提交解决方案'],['ticket.close','关闭工单'],['ticket.supplement.request','请求补充资料'],['ticket.cancel.review','审核取消'],['ticket.transfer.request','发起转派'],['ticket.reopen.review','审核重开'],['ticket.respond','客户可见回复'],['approval.parts.read','查看备件申请'],['approval.parts.submit','提交备件申请'],['approval.parts.review','审批备件申请'],['stock.read','查看库存'],['stock.manage','执行库存'],['finance.quote.read','查看报价'],['finance.quote.write','编制报价'],['approval.fees.read','查看费用审批'],['approval.fees.submit','提交费用审批'],['approval.fees.review','主管审批费用'],['approval.fees.finance','财务审批费用'],['finance.money.read','查看资金'],['finance.money.assess','登记应收'],['finance.money.adjust','调整应收'],['finance.money.collect','登记收款'],['finance.money.reverse','冲正错录'],['finance.money.refund','登记退款']] as const
const form=reactive({department:'',companies:'',assignment:'',approval:'',reopen:'',warehouses:'',capabilities:[] as string[],reason:''}),busy=ref(false),message=ref(''),observed=ref(false),pending=ref<EmployeeScopeCommand|null>(null);let alive=true
const key=computed(()=>`ias.employee.scope.${auth.identity?.tenant?.id||''}.${auth.identity?.userId||''}.${props.access.userId}`),allowed=computed(()=>auth.identity?.realm==='TENANT'&&auth.identity.permissions.includes('identity.employee.manage')&&auth.identity.userId!==props.access.userId&&!props.access.capabilities.some(x=>['identity.employee.manage','identity.session.revoke'].includes(x)))
watch(()=>[key.value,props.access.securityVersion],()=>{pending.value=null;observed.value=false;try{const raw=sessionStorage.getItem(key.value);if(raw)pending.value=JSON.parse(raw)}catch{message.value='无法读取原操作，请联系管理员核验。'}if(!pending.value){form.department=props.access.departmentId||'';form.companies=props.access.companyIds.join(',');form.assignment=props.access.assignmentDepartmentIds.join(',');form.approval=props.access.approvalDepartmentIds.join(',');form.reopen=props.access.reopenDepartmentIds.join(',');form.warehouses=props.access.warehouseIds.join(',');form.capabilities=props.access.capabilities.filter(x=>choices.some(c=>c[0]===x));form.reason=''}},{immediate:true})
function ids(text:string){if(!text.trim())return [];const values=text.split(/[,，\s]+/).filter(Boolean);if(values.length>100||values.some(x=>!/^[1-9][0-9]{0,18}$/.test(x))||new Set(values).size!==values.length)throw Error('范围编号必须是互不重复的正整数。');return values}
function clear(){sessionStorage.removeItem(key.value);pending.value=null;observed.value=false}
async function send(){if(!allowed.value||!auth.csrf||busy.value)return;if(!pending.value){try{if(form.department&&!/^[1-9][0-9]{0,18}$/.test(form.department))throw Error('部门编号无效。');if(Array.from(form.reason).length<5||Array.from(form.reason).length>200)throw Error('变更原因须为 5～200 个字符。');pending.value={operationId:crypto.randomUUID(),expectedSecurityVersion:props.access.securityVersion,departmentId:form.department||null,capabilities:[...form.capabilities],companyIds:ids(form.companies),assignmentDepartmentIds:ids(form.assignment),approvalDepartmentIds:ids(form.approval),reopenDepartmentIds:ids(form.reopen),warehouseIds:ids(form.warehouses),reason:form.reason};sessionStorage.setItem(key.value,JSON.stringify(pending.value))}catch(e){message.value=e instanceof Error?e.message:'请检查输入。';return}}else if(!observed.value)return
 const command={...pending.value},target=props.access.userId,scope=captureRequestScope(auth,()=>alive&&pending.value?.operationId===command.operationId&&props.access.userId===target);busy.value=true;try{const result=await api.employeeScope(target,command,auth.csrf.token);if(!scope.current())return;if(result.operationId!==command.operationId||result.userId!==target)throw Error('回执不匹配');clear();message.value='授权已更新，员工旧会话已失效。';emit('changed')}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status>0&&e.status<500&&e.status!==401&&e.status!==403){clear();message.value=`授权未更新：${e.code}，请核对范围及版本。`}else{observed.value=false;message.value='结果尚未确认，请先查询原操作。'}}finally{if(scope.current()||!pending.value)busy.value=false}}
async function query(){if(!pending.value||busy.value)return;const op=pending.value.operationId,target=props.access.userId,scope=captureRequestScope(auth,()=>alive&&pending.value?.operationId===op&&props.access.userId===target);busy.value=true;try{const result=await api.employeeScopeOperation(target,op);if(!scope.current())return;if(result.operationId!==op||result.userId!==target)throw Error('回执不匹配');clear();message.value='原授权操作已完成。';emit('changed')}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status===404&&e.code==='OPERATION_NOT_OBSERVED'){observed.value=true;message.value='尚未观察到原操作，可核对原参数后显式继续。'}else message.value='原操作无法确认，请稍后再查。'}finally{if(scope.current()||!pending.value)busy.value=false}}
onUnmounted(()=>{alive=false})
</script>
<template><section v-if="allowed" class="panel"><h2>设置员工授权</h2><p>只填写本租户内已存在的编号；多个编号用逗号分隔。保存会替换以下范围，并使员工旧会话失效。</p><template v-if="!pending"><label>所属部门编号 <input v-model.trim="form.department"></label><label>客户企业编号 <input v-model="form.companies"></label><label>可分派部门编号 <input v-model="form.assignment"></label><label>审批部门编号 <input v-model="form.approval"></label><label>重开审核部门编号 <input v-model="form.reopen"></label><label>仓库编号 <input v-model="form.warehouses"></label><fieldset><legend>业务能力</legend><label v-for="choice in choices" :key="choice[0]"><input v-model="form.capabilities" type="checkbox" :value="choice[0]">{{ choice[1] }}</label></fieldset><label>变更原因 <input v-model="form.reason" maxlength="200"></label><button :disabled="busy" @click="send">确认更新授权</button></template><template v-else><p>原操作：{{ pending.operationId }} · 原因：{{ pending.reason }}</p><button :disabled="busy" @click="query">查询原授权操作</button><button v-if="observed" :disabled="busy" @click="send">显式按原参数继续</button></template><p v-if="message" role="status">{{ message }}</p></section></template>

